insert into public.pages (id, slug, kind, title, description, sections, baseline_order, status, published_at)
values ('70ea7ea5-1bde-5d4a-84e8-a6714860615c', '', 'core'::public.page_kind, 'אלונה אקרלינג', null,
        '[{"id":"hero","type":"home-hero","schema_version":1,"visible":true,"payload":{"kicker":"תזונת נשים · ליווי אישי","title":"את כבר יודעת מה לאכול.\nמה שחסר זה לא עוד תפריט.","titleAccent":"לא עוד תפריט","lede":"אלא דרך שנבנית סביב השבוע האמיתי שלך, והאוכל שאת אוהבת נשאר בפנים. שקט בראש, ותוצאה שנשארת.","ctaPrimary":"בואי נדבר","trustToken":"דיאטנית קלינית מוסמכת · R.D.","trustTokenLicense":" · רישיון משרד הבריאות","ctaRecipes":"עוד לא מוכנה לשיחה? המתכונים שלי כאן","imageAlt":"מגדל פנקייקים עם תאנים, אוכמניות ובננה על צלחת לבנה, על שיש בהיר, מהמטבח של אלונה","image":"/media/client/alona/dish-protein-pancakes.jpg"}},{"id":"guide","type":"home-guide","schema_version":1,"visible":true,"payload":{"kicker":"נעים להכיר","title":"אני מכירה את הבלבול הזה","empathy":"גם אני עמדתי מול הבלגן הזה, עד שכבר לא ידעתי מה נכון ומה לא נכון. בדיוק בגלל זה הלכתי ללמוד: להבין מה באמת קורה בגוף שלנו.","empathyAccent":"להבין מה באמת קורה בגוף שלנו","name":"אלונה אקרלינג","role":"דיאטנית קלינית מוסמכת · R.D.","portraitAlt":"אלונה אקרלינג, דיאטנית קלינית מוסמכת, אוכלת מקערה במטבח שלה","cta":"בואי לראות איך עובדים יחד ←","titleAccent":"מכירה","credentials":["דיאטנית קלינית מוסמכת · R.D.","רישיון משרד הבריאות 204526-11","B.Sc במדעי התזונה","התמחות קלינית · איכילוב"],"introHello":"היי, אני אלונה.","intro":"דיאטנית קלינית שגם מבשלת באמת, כל שבוע, במטבח שלי. אני מלווה אחת-על-אחת, בדרך שנבנית סביב השבוע האמיתי שלך ונשענת על המדע הכי עדכני. ומה שהכי חשוב לי: שנדבר בגובה העיניים.","areasLabel":"תחומי ליווי","areas":["תזונת הריון","שחלות פוליציסטיות (PCOS)","טרום סוכרת ואיזון מדדי דם","ירידה במשקל בלי דיאטה","אכילה רגשית"],"areasNote":"בתחומים הרפואיים אני עובדת לצד הרופא או הרופאה שמלווים אותך, לא במקומם.","portrait":"/media/client/alona/alona-guide.jpg"}},{"id":"ribbon","type":"home-ribbon","schema_version":1,"visible":true,"payload":{"kicker":"מהמטבח שלי","note":"כל מתכון כאן נבדק אצלי בבית לפני שהוא מגיע אלייך. אלה לא צילומי מאגר.","follow":"כל מנה כאן עלתה קודם לאינסטגרם. שם עולים מתכונים חדשים, טיפים קטנים, ומה שבאמת קורה במטבח ביום רגיל.","linkHint":"לצפייה באינסטגרם, נפתח בלשונית חדשה","tiles":[{"src":"/media/client/alona/ribbon/kale-chickpea.jpg","alt":"קערת עלים ירוקים עם חומוס קלוי ובצל סגול כבוש"},{"src":"/media/client/alona/ribbon/pancakes-figs.jpg","alt":"מגדל פנקייקים עם תאנים, בננה ואוכמניות"},{"src":"/media/client/alona/ribbon/roasted-tray.jpg","alt":"תבנית ירקות שורש צלויים עם רוזמרין ולימון"},{"src":"/media/client/alona/ribbon/fruit-bowl.jpg","alt":"קערת פירות חתוכים: מלון, אבטיח, קיווי ואוכמניות"},{"src":"/media/client/alona/ribbon/pepper-salad.jpg","alt":"סלט פלפלים צבעוניים, מלפפון ובצל"},{"src":"/media/client/alona/ribbon/cauliflower-dip.jpg","alt":"כרובית פריכה בציפוי זהוב לצד רוטב ירוק"},{"src":"/media/client/alona/ribbon/fritters-tray.jpg","alt":"תבנית אפייה מלאה בלביבות זהובות"},{"src":"/media/client/alona/ribbon/chickpea-bowl.jpg","alt":"קערה עם חומוס קלוי, עלים ירוקים ובצל כבוש"},{"src":"/media/client/alona/ribbon/quinoa-platter.jpg","alt":"מגש קינואה עם ירק קצוץ ושקדים"},{"src":"/media/client/alona/ribbon/lasagna-basil.jpg","alt":"לזניה בתבנית עם עלי בזיליקום טריים"},{"src":"/media/client/alona/ribbon/green-pasta.jpg","alt":"מחבת פסטה ברוטב ירוק עם גבינה מגוררת"},{"src":"/media/client/alona/ribbon/focaccia.jpg","alt":"פוקצ''ה ביתית עם שומשום וזיתים"},{"src":"/media/client/alona/ribbon/rice-pan.jpg","alt":"מחבת אורז צהוב עם ירקות"}]}},{"id":"plan","type":"home-plan","schema_version":1,"visible":true,"payload":{"kicker":"איך זה עובד","title":"שלושה צעדים, בשפה שלך","lead":"תפריטים כבר יש לך. הדרך צריכה להיבנות סביב השבוע שלך.","cta":"רוצה לראות איך זה נראה בפועל? הצצה למטבח שלי ←","titleAccent":"בשפה שלך","steps":[{"n":"01","t":"שיחת היכרות","d":"שיחה קצרה, בחינם ובלי שום התחייבות. את מספרת לי מה עובר עלייך עכשיו, מה כבר ניסית, ומה הכי מעייף אותך סביב האוכל, ואני בעיקר מקשיבה. בסוף השיחה נבין ביחד אם אני האדם הנכון ללוות אותך, ואם התשובה היא לא, אגיד לך את זה בכנות. זו שיחה, לא שיחת מכירה, ואת לא צריכה להגיע אליה מוכנה."},{"n":"02","t":"פגישה עמוקה + תוכנית אישית","d":"פגישה של 60 עד 75 דקות שיושבת לעומק: מה את אוהבת לאכול, איך נראה היום שלך באמת, מה כבר ניסית ומה נשבר בדרך, ובדיקות דם אם רלוונטי. אין כאן שיפוט ואין רשימת איסורים, יש הקשבה למה שבאמת קורה אצלך בשבוע. מהפגישה את יוצאת עם תוכנית אישית שנבנית סביב החיים שלך ולא במקומם, והאוכל שאת אוהבת נשאר בפנים. התוכנית נשארת אצלך, ולא נעלמת ברגע שיצאת מהחדר."},{"n":"03","t":"ליווי שנשאר","d":"אני לא נעלמת אחרי הפגישה, וזה בדיוק החלק שרוב הדיאטות מפספסות. בחבילות הליווי אני איתך בוואטסאפ בין המפגשים, לשאלות הקטנות שצצות באמצע היום ולרגעים שבהם מתחשק לוותר, ויש גם פידבק על יומן האכילה ומפגשי מעקב לאורך הדרך. ככה הדברים מפסיקים להיות רעיון יפה ונכנסים לשגרה, גם בשבועות העמוסים. המטרה שלי היא שלא תישארי לבד מול האתגרים של היום יום, ושבסוף הדרך יישאר לך משהו שהוא כבר שלך. לא עוד דיאטה שנגמרת."}]}},{"id":"proof","type":"home-proof","schema_version":1,"visible":true,"payload":{"kicker":"תראי בעצמך","title":"אני באמת מבשלת","body":"לא עוד תמונה יפה. אוכל אמיתי שאני מבשלת, מתוך שבוע רגיל ועמוס.","countChip":"55 מתכונים · מתכון חדש כל שבוע","cta":"לכל המתכונים ←","titleAccent":"באמת"}},{"id":"stakes","type":"home-stakes","schema_version":1,"visible":true,"payload":{"kicker":"נמאס מהסבב הזה?","title":"עוד שנה רועשת, או דרך שסוף-סוף שקטה","cue":"הדרך שאני ממליצה עליה","band":"במקום עוד שנה כזאת, בואי נדבר. שיחת היכרות בלי עלות ובלי התחייבות.","bandCta":"בואי נדבר ←","bandSecondary":"או קחי בינתיים הצצה למתכונים","titleAccent":"שקטה","quiet":{"label":"הדרך השקטה","note":"פעם אחת, בליווי, והאוכל שאת אוהבת נשאר על השולחן","points":["דרך שנבנית סביב השבוע האמיתי שלך","שקט. לאכול בלי לספור ובלי להתנצל","משהו שנשאר איתך, כי זו לא עוד דיאטה","אחת-על-אחת, גם בין הפגישות"]},"noisy":{"label":"עוד שנה רועשת","note":"עוד דיאטה שמתחילה ביום ראשון ונשברת ברביעי","points":["תפריט חדש שאת כבר יודעת שלא יחזיק","רעש בראש סביב כל ארוחה, ואשמה אחריה","\"הפעם זה יחזיק\", שכבר אמרת לעצמך","לבד מול עוד ניסיון"]}}},{"id":"articles","type":"home-articles","schema_version":1,"visible":true,"payload":{"kicker":"מאמרים","titleA":"מה שאני מסבירה בקליניקה, ","titleAccent":"כתוב כאן","lead":"בלי קיצורי דרך ובלי הפחדות.","itemCta":"לקריאה ←","allCta":"לכל המאמרים ←"}},{"id":"success","type":"home-success","schema_version":1,"visible":true,"payload":{"kicker":"ככה זה יכול להרגיש","lines":"בפעם הראשונה, אני לא בדיאטה.\nאכלתי בחוץ, נהניתי, ובלי אשמה.\nיש לי אנרגיה, ובראש שקט.","bridge":"וזה מתחיל בשיחה אחת, בלי לחץ. ←"}},{"id":"cta","type":"home-cta","schema_version":1,"visible":true,"payload":{"title":"בואי נדבר.\nהצעד הראשון קטן, וחינם.","body":"שיחת היכרות קצרה, בלי התחייבות. נכיר, ונבין יחד אם אני האדם הנכון ללוות אותך אל השקט הזה.","packages":"הליווי נמכר בחבילות שמתאימות לחיים שלך. על זה בדיוק נדבר בשיחה, בלי הפתעות ובלי מחיר שקופץ מהמסך.","promise":"אני חוזרת אלייך אישית, עד 4 ימי עסקים.","trustToken":"דיאטנית קלינית מוסמכת · R.D.","trustTokenLicense":" · רישיון משרד הבריאות"}}]'::jsonb,
        '[{"id":"hero","type":"home-hero"},{"id":"guide","type":"home-guide"},{"id":"ribbon","type":"home-ribbon"},{"id":"plan","type":"home-plan"},{"id":"proof","type":"home-proof"},{"id":"stakes","type":"home-stakes"},{"id":"articles","type":"home-articles"},{"id":"success","type":"home-success"},{"id":"cta","type":"home-cta"}]'::jsonb, 'published', now())
on conflict (id) do update set
  title = excluded.title,
  description = excluded.description,
  sections = excluded.sections;
