-- The FULL documents — hidden sections included — go to drafts, which has no
-- anon policy at all. The pages rows above hold only the visible projection,
-- so without these rows a section hidden at migration time would exist
-- NOWHERE in the database, and the desk could never show or unhide it again.
-- The desk reads drafts-first for exactly this reason.
insert into public.drafts (entity_type, entity_id, payload)
values ('page', '105b8030-6649-53c5-805a-b2a3fcb1f9c7', '{"slug":"about","title":"עליי","sections":[{"id":"hero","type":"about-hero","schema_version":1,"visible":true,"payload":{"crumbLabel":"עליי","kicker":"נעים להכיר","title":"אלונה אקרלינג","lede":"דיאטנית קלינית מוסמכת שמלווה נשים אל שקט סביב האוכל, בגובה העיניים, בלי דיאטות ובלי אשמה. הנה מי שעומדת מאחורי כל מילה כאן.","licenseChip":"דיאטנית קלינית מוסמכת · R.D. · רישיון משרד הבריאות 204526-11","ctaPrimary":"בואי נדבר","ctaPrimarySub":"שיחת היכרות בלי עלות","ctaMicro":"תראי בעצמך אם זה מתאים · בלי התחייבות","ctaSecondary":"קראי את הסיפור שלי ↓","portraitLabel":"אלונה אקרלינג, דיאטנית קלינית מוסמכת, פורטרט"}},{"id":"story","type":"about-story","schema_version":1,"visible":true,"payload":{"kicker":"הסיפור שלי","title":"לפני שהייתי דיאטנית,\nהייתי בדיוק במקום שלך","p1":"הכל התחיל אצלי בתקופת הקורונה, כשגיליתי את הבישול הבריא והתחלתי לשתף באינסטגרם.","p2":"ואז טבעתי במיתוסים: בשלב מסוים כבר לא ידעתי מה נכון ומה לא נכון. בדיוק בגלל זה הלכתי ללמוד, כדי להבין מה באמת קורה בגוף שלנו.","credo1":"אני מאמינה שאוכל בריא לא צריך להיות משעמם. להפך: הוא יכול להיות עשיר, מגוון, טעים וצבעוני, ולא מסובך בכלל.","credo2":"אין מאכלים אסורים, אין אשמה. רק איזון חכם שמאפשר ליהנות מהכל.","credo2Accent":"ליהנות","signOff":"זמינה בשבילך לכל שאלה,","signature":"אלונה","image":"/media/client/recipes/light-cheese-lasagna-2.webp","imageAlt":"לזניה גבינה קלילה בתבנית עם עלי בזיליקום, מנה אמיתית מהמטבח של אלונה"}},{"id":"standard","type":"about-standard","schema_version":1,"visible":true,"payload":{"kicker":"הסטנדרט שלי","title":"בתזונה אפשר להגיד כמעט הכל.\nאני עובדת אחרת.","titleAccent":"אחרת","body":"זה תחום פרוץ. כמעט כל אחד יכול לפתוח עמוד ולתת עצות, ואין מי שיבדוק אותן. אני בחרתי בדרך הארוכה: תואר, התמחות קלינית, רישיון של משרד הבריאות, והמון שעות של קריאה ועדכון מאחורי כל תשובה. לכל המלצה שאת מקבלת ממני יש מקור. וכשהמחקר משתנה, גם ההמלצה משתנה.","principles":[{"t":"כל המלצה נשענת על מחקר","d":"לא על הטרנד של החודש, ולא על מה שעבד למישהי אחרת בתנאים אחרים."},{"t":"רישיון שאפשר לבדוק","d":"רישיון משרד הבריאות 204526-11, פתוח לבדיקה של כל אחת במאגר."},{"t":"בתחום רפואי, לצד הרופא/ה","d":"בהריון, בשחלות פוליציסטיות ובטרום סוכרת אני עובדת לצד הצוות הרפואי שמלווה אותך, לא במקומו."}],"areasLabel":"התחומים שאני מלווה בהם","areas":["תזונת הריון","שחלות פוליציסטיות (PCOS)","טרום סוכרת ואיזון מדדי דם","ירידה במשקל בלי דיאטה","אכילה רגשית"]}},{"id":"road","type":"about-road","schema_version":1,"visible":true,"payload":{"kicker":"הדרך לכאן","title":"הדרך לא התחילה בקליניקה.\nהיא התחילה במטבח.","titleAccent":"במטבח","p1":"בתקופת הקורונה גיליתי את הבישול הבריא, והתחלתי לשתף באינסטגרם. וככל ששיתפתי יותר, נכנסו לחיים שלי יותר קולות: כל אחד אמר משהו אחר, וכולם נשמעו בטוחים לגמרי.","p2":"בשלב מסוים טבעתי במיתוסים, עד שכבר לא ידעתי בעצמי מה נכון ומה לא. שם הבנתי שלא מספיקה לי עוד דעה, אני רוצה לדעת באמת. הלכתי ללמוד תואר במדעי התזונה, המשכתי להתמחות קלינית באיכילוב, והוצאתי רישיון של משרד הבריאות.","p3":"בחרתי במקצוע הזה בגלל הבלבול שהייתי בתוכו בעצמי. רציתי להיות התשובה שחיפשתי אז: מקום אחד שקט, שבו ההמלצות נשענות על מדע, נאמרות בגובה העיניים, והאוכל נשאר טעים ומהנה.","roleLine":"דיאטנית קלינית מוסמכת · R.D.","recordsLabel":"הרשומות","records":["דיאטנית קלינית מוסמכת · R.D. · רישיון משרד הבריאות 204526-11","B.Sc במדעי התזונה · המרכז האקדמי פרס, 2024","התמחות קלינית · בית החולים איכילוב · חצי שנה, 2025","קורס בתזונת הריון · לימודי המשך, מעבר לתואר"],"bridge":"ואם הבלבול הזה מרגיש לך מוכר, הצעד הראשון שלך יכול להיות דומה לשלי: להפסיק לנחש, ולהתחיל להבין מה נכון לך.","bridgeCta":"בואי נדבר, שיחת היכרות בלי עלות ←"}},{"id":"cta","type":"about-cta","schema_version":1,"visible":true,"payload":{"kicker":"הצעד שלך","title":"עכשיו כשאת מכירה אותי,\nבשיחת היכרות בלי עלות, תראי בעצמך אם זה מתאים.","body":"עכשיו את כבר יודעת מאיפה אני מגיעה ומה הרקע שלי. מה שנשאר זה לשמוע אותך: שיחה קצרה, בלי עלות ובלי התחייבות, בגובה העיניים, ונראה אם הדרך שלי מתאימה לך. האוכל שאת אוהבת נשאר בפנים.","recipes":"ורוצה קודם פשוט לראות מה אני מבשלת? המתכונים כאן ←","socialLabel":"ואם בא לך קודם לראות אותי ביומיום","trustToken":"דיאטנית קלינית מוסמכת · R.D. · רישיון משרד הבריאות 204526-11","promise":"אני חוזרת אלייך אישית, עד 4 ימי עסקים.","button":"בואי נדבר, שיחת היכרות חינם","signature":"אלונה"}}],"baseline_order":[{"id":"hero","type":"about-hero"},{"id":"story","type":"about-story"},{"id":"standard","type":"about-standard"},{"id":"road","type":"about-road"},{"id":"cta","type":"about-cta"}]}'::jsonb)
on conflict (entity_type, entity_id) do update set
  payload = excluded.payload,
  updated_at = now();
