values ('page', '3ee8653c-e193-569e-83ce-1c7d03fb0ef9', '{"slug":"coaching","title":"איך עובדים איתי","sections":[{"id":"meta","type":"page-meta","schema_version":1,"visible":true,"payload":{"title":"איך עובדים איתי","serviceName":"ליווי תזונתי אישי","serviceType":"ליווי תזונתי אישי"}},{"id":"hero","type":"coaching-hero","schema_version":1,"visible":true,"payload":{"breadcrumb":"איך עובדים איתי","kicker":"ליווי אחת-על-אחת","title":"ככה נעבוד ביחד","body":"את כבר יודעת מה לאכול. הדרך צריכה להיבנות סביב השבוע שלך, בלי לוותר על האוכל שאת אוהבת, כדי שסוף-סוף יהיה שקט בראש והתוצאה תישאר.","trustToken":"דיאטנית קלינית מוסמכת · R.D. · רישיון משרד הבריאות 204526-11","ctaPrimary":"בואי נדבר","ctaSub":"שיחת היכרות חינם","ctaWhatsapp":"אפשר גם לכתוב לי בוואטסאפ","micro":"בלי התחייבות · מענה עד 4 ימי עסקים · על החבילות נדבר בשיחה"}},{"id":"problem","type":"coaching-problem","schema_version":1,"visible":true,"payload":{"kicker":"למה דווקא ליווי","title":"את כבר יודעת מה לאכול","titleAccent":"יודעת","lead":"מה שחסר זה לא עוד ידע.","body1":"שמרת את הפוסטים, קראת את התפריטים, התחלת ביום ראשון. ולבד, שוב, זה לא החזיק, וזה לא כי טעית או לא ניסית מספיק.","quote":"הפער הוא לא במה לאכול. הפער הוא לעשות את זה לבד.","quoteAccent":"לבד","body2":"הידע כבר אצלך; מה שאף מדריך לא נתן לך זה מישהי לצדך, בתוך השבוע האמיתי שלך.","cta":"אז ככה זה עובד כשלא לבד ←"}},{"id":"method","type":"coaching-method","schema_version":1,"visible":true,"payload":{"kicker":"שיטה, לא קסם","title":"ארבעה דברים שהופכים ידע לתוצאה שנשארת","titleAccent":"שנשארת","pillars":[{"title":"נבנה סביב השבוע האמיתי שלך","body":"לא תפריט גנרי שנלחם בחיים שלך, אלא דרך שנבנית סביב מה שבאמת קורה אצלך בשבוע: העבודה, הילדים, האירועים, והערב שבו אין כוח לבשל. בגלל זה זה מחזיק."},{"title":"בלי לוותר על האוכל שאת אוהבת","body":"אנחנו לא מוחקות מאכלים ולא עושות רשימות אסור. לומדות איך לשלב את מה שאת אוהבת בתוך משהו שעובד, בלי אשמה, כדי שיהיה שקט בראש."},{"title":"החלטות על סמך מדע עדכני","body":"כל החלטה נשענת על מה שידוע היום על הגוף, לא על הדיאטה הבאה שכולם מדברים עליה. זה ההבדל בין ניחוש לבין שיטה."},{"title":"ליווי צמוד גם בין הפגישות","body":"אני איתך בין הפגישות, לא רק בחדר: כדי שהידע יהפוך להרגל, ושלא תישארי לבד באמצע הדרך."}],"cta":"ככה זה נראה בפועל, הנה החבילות ←"}},{"id":"packages","type":"coaching-packages","schema_version":1,"visible":true,"payload":{"kicker":"שלוש דרכים להיכנס","title":"בחרי את הליווי שמתאים לך","titleAccent":"שמתאים לך","lead":"אותה שיטה, בשלוש רמות של ליווי. בלי מחיר קשיח: נבחר ביחד את מה שמתאים לחיים שלך, בשיחת היכרות בלי התחייבות.","facts":["60 עד 75 דקות","ליווי בסיס · 60 יום","ליווי מורחב · 7 מפגשים","מענה עד 4 ימי עסקים"],"fitLabel":"למי זה מתאים:","includedLabel":"מה כלול:","cardCta":"בואי נדבר","sharedLine":"על החבילה והמחיר נדבר בשיחה. נתאים אותם אלייך, בלי התחייבות.","packages":[{"slug":"single-session","name":"פגישת עומק · חד-פעמית","chip":"60 עד 75 דקות","fit":"לרגע שבו את רוצה כיוון מקצועי אחד, נקי: פגישה עמוקה ותוכנית אישית שנשארת איתך.","included":["אבחון מעמיק בפגישה של 60 עד 75 דקות","תוכנית אישית שנבנית סביב השבוע שלך","קובץ מפורט עם כלים, טיפים והנחיות להתנהלות עצמאית"],"highlight":false},{"slug":"coaching-60","name":"ליווי בסיס · 60 יום","chip":"","fit":"כשאת רוצה לא רק לדעת מה נכון, אלא שמישהי תלווה אותך עד שזה נכנס לשגרה.","included":["פגישת אבחון מעמיקה + 4 מפגשי מעקב (אחת לשבועיים)","וואטסאפ ביני לבינך בין המפגשים","פידבק על יומן האכילה","צירוף לקבוצת הוואטסאפ + גישה לאפליקציה ותכנים מקצועיים"],"highlight":false},{"slug":"coaching-120","name":"ליווי מורחב · 120 יום","chip":"7 מפגשים · 4 חודשים","fit":"מתאים כשהדפוס ותיק וניסית כבר הכל, וחשוב לך שהפעם זה יישאר.","included":["7 מפגשים לאורך 120 יום: פגישת אבחון מעמיקה + 6 מפגשי מעקב","ארבעה חודשים של ליווי, הזמן שלוקח להרגל להפוך לשגרה","וואטסאפ ביני לבינך בין המפגשים, לאורך כל התקופה","פידבק על יומן האכילה","צירוף לקבוצת הוואטסאפ + גישה לאפליקציה ותכנים מקצועיים"],"highlight":true}]}},{"id":"process","type":"coaching-process","schema_version":1,"visible":true,"payload":{"kicker":"שלב אחרי שלב","title":"מה קורה בכל שלב","lead":"בחרת כיוון? הנה מה שקורה בפועל, בלי הפתעות: אותה דרך חמה, אחת-על-אחת, שנבנית סביב השבוע שלך.","steps":[{"t":"שיחת היכרות","d":"בחינם ובלי התחייבות. נכיר, תספרי לי מה עובר עלייך, ונבין ביחד אם אני האדם הנכון ללוות אותך. שיחה, לא שיחת מכירה."},{"t":"פגישה עמוקה + תוכנית אישית","d":"60 עד 75 דקות שיושבות לעומק: מה את אוהבת לאכול, איך נראה היום שלך, מה כבר ניסית, ובדיקות דם אם רלוונטי. את יוצאת עם תוכנית שנבנית סביב החיים שלך, לא במקומם."},{"t":"ליווי שנשאר","d":"כאן זה לא נגמר. בין המפגשים אני איתך בוואטסאפ, עם פידבק על יומן האכילה, ובחבילות גם אפליקציית ליווי, כדי שהדברים ייכנסו לשגרה ויישארו. לא עוד דיאטה שנגמרת ואת נשארת לבד איתה."}],"cta":"מרגישה שזה מדבר אלייך? בואי נדבר ←"}},{"id":"proof","type":"coaching-proof","schema_version":1,"visible":true,"payload":{"kicker":"תראי בעצמך","title":"מהמטבח של אלונה","titleAccent":"אלונה","lead":"אוכל שאני באמת מבשלת, בתוך שבוע רגיל, בלי למחוק את מה שאת אוהבת.","photo":"/media/client/recipes/baked-bulgur-lentil-mujadara.webp","photoAlt":"מג׳דרת בורגול ועדשים בתנור","tiles":[{"src":"/media/client/recipes/oven-fried-rice-tofu.webp","alt":"אורז מוקפץ בתנור עם ירקות וטופו"},{"src":"/media/client/recipes/hearty-lentil-soup.webp","alt":"מרק עדשים עשיר ומנחם"}],"testimonialEmpty":"המלצות אמיתיות יופיעו כאן ברגע שיהיו. אני לא ממציאה סיפור שלא קרה.","cta":"הצצה למטבח שלי ←"}},{"id":"faq","type":"coaching-faq","schema_version":1,"visible":true,"payload":{"kicker":"לפני שנדבר","title":"כל מה שאת שואלת את עצמך עכשיו","lead":"ריכזתי כאן את השאלות שחוזרות אליי הכי הרבה, בכנות, בלי מכירה. אם נשאר לך עוד משהו, בדיוק בשביל זה יש שיחת היכרות בלי התחייבות.","items":[{"q":"אני כבר יודעת מה לאכול. אז מה ליווי בכלל ייתן לי?","a":"רוב הנשים שמגיעות אליי יודעות בדיוק מה נכון. הפער אף פעם לא היה בידע, הוא בלעשות את זה לבד, בתוך שבוע עמוס. הליווי הוא לא עוד מידע: הוא דרך שנבנית סביב השבוע האמיתי שלך, ומישהי אחת שנשארת איתך עד שזה נכנס לשגרה."},{"q":"ניסיתי כבר הכל. למה שדווקא זה יעבוד?","a":"כי זה לא עוד דיאטה ולא עוד תפריט. אין אצלי קיצורי דרך, טרנדים והבטחות קסם: בונות דרך סביב החיים שלך, בלי לוותר על האוכל שאת אוהבת, בקצב שאפשר להתמיד בו."},{"q":"אני לא רוצה עוד תפריט נוקשה שאי אפשר לעמוד בו.","a":"ואני לא עובדת ככה. אין תפריט אחיד ואין רשימת איסורים: יש התאמה לשבוע שלך, לטעמים שלך ולקצב שלך, וגמישות כשהחיים משתנים."},{"q":"יש לי כל הזמן רעש ואשמה בראש סביב אוכל. זה יכול להשתנות?","a":"זה בדיוק הלב של העבודה שלי. המטרה היא שקט: פחות התלבטות, פחות אשמה, יותר ראש נקי. בלי שיפוט ובלי \"נפלת\"."},{"q":"אני אוכלת הרבה מתוך לחץ או רגש. את מתייחסת גם לזה?","a":"כן, זה חלק מרכזי בליווי. מסתכלות יחד על הדפוסים בעדינות, בלי שיפוט, ובונות במקומם הרגלים שקטים יותר ומערכת יחסים טובה יותר עם אוכל."},{"q":"איך אני יודעת שהפעם זה יישאר ולא יחזור כמו תמיד?","a":"כי אנחנו לא רודפות אחרי תוצאה מהירה שנעלמת. בונות הרגלים באמת, בקצב שנכון לך, כך שאפשר להתמיד לאורך זמן. הליווי המורחב קיים בדיוק בשביל זה."},{"q":"מה קורה אחרי שהליווי נגמר? אני חוזרת לאותו מקום?","a":"המטרה שלי הפוכה מתלות: שתצאי עם דרך שהיא כבר שלך. תוכנית שנשארת בידיים שלך, הרגלים שהפכו טבעיים, וכלים שיישארו גם הרבה אחרי שהליווי יסתיים."},{"q":"אני מרגישה שאני מתמודדת עם זה לבד. איך הליווי עוזר בזה?","a":"בזה שאני באמת שם. יש פגישות אחת-על-אחת, ובחבילות הליווי גם וואטסאפ ביני לבינך בין המפגשים, עם פידבק על יומן האכילה. המטרה היא שלא תישארי לבד מול האתגרים של היום יום."},{"q":"את בת 26. יש לך מספיק ניסיון, או שאת עוד אינפלואנסרית?","a":"שאלה הוגנת. אני דיאטנית קלינית מוסמכת, רישיון משרד הבריאות 204526-11 (אפשר לבדוק במאגר משרד הבריאות), עם B.Sc במדעי התזונה והתמחות קלינית בבית החולים איכילוב. ואני דווקא חושבת שהגיל הוא יתרון: אני מגיעה עם אנרגיה, סקרנות ורצון ללמוד ולהתפתח. את כל הסיפור תמצאי בעמוד \"עליי\"."},{"q":"אין לי זמן וכוח לעוד פרויקט גדול. איך זה משתלב בחיים?","a":"זה בכוונה לא פרויקט ענק. בונים את התהליך סביב החיים האמיתיים: גם אם את עובדת שעות ארוכות, אוכלת בחוץ או כמעט לא מבשלת, נמצא יחד מה שעובד אצלך. ויש גם פגישת עומק חד-פעמית, למי שרוצה כיוון בלי התחייבות ארוכה."},{"q":"אינסטגרם מלא בתוכן חינם. למה בכלל לשלם על ליווי?","a":"תוכן חינם הוא נהדר, אבל הוא כללי ומיועד לכולם, ולכן קל לדעת ולא לעשות. ליווי נותן ארבעה דברים שפוסט לא ייתן: התאמה אישית, מבנה, מישהי שבאמת חוזרת אלייך, וקהילה של בנות באותה דרך. המידע חינם; מה שמחזיק לאורך זמן זה הליווי."}],"closeLine":"נשאר לך \"כן, אבל\" שלא מופיע כאן? בשיחת היכרות בלי עלות ובלי התחייבות נענה עליו יחד.","closeCta":"בואי נדבר ←","magnet":"עדיין לא בטוחה? הצצה למטבח שלי."}},{"id":"cta","type":"coaching-cta","schema_version":1,"visible":true,"payload":{"title":"הגעת עד לפה.\nנשאר רק להכיר. בואי נדבר.","body":"שיחת היכרות קצרה, בלי התחייבות. נכיר, ונבין יחד אם אני האדם הנכון ללוות אותך, בלי לוותר על האוכל שאת אוהבת, כדי שסוף-סוף יהיה שקט בראש.","packagesLine":"הליווי נמכר בחבילות שמתאימות לחיים שלך. על זה נדבר בשיחה, בלי הפתעות ובלי מחיר שקופץ מהמסך.","promise":"אני חוזרת אלייך אישית, עד 4 ימי עסקים.","trustToken":"דיאטנית קלינית מוסמכת · R.D. · רישיון משרד הבריאות 204526-11","aboutPointer":"רוצה קודם להכיר אותי? הסיפור שלי בעמוד עליי ←","formHeading":"בואי נדבר, שיחת היכרות חינם"}}],"baseline_order":[{"id":"meta","type":"page-meta"},{"id":"hero","type":"coaching-hero"},{"id":"problem","type":"coaching-problem"},{"id":"method","type":"coaching-method"},{"id":"packages","type":"coaching-packages"},{"id":"process","type":"coaching-process"},{"id":"proof","type":"coaching-proof"},{"id":"faq","type":"coaching-faq"},{"id":"cta","type":"coaching-cta"}]}'::jsonb)
