values ('page', 'e99e9eca-8d71-517e-8456-1c385339da0a', '{"slug":"contact","title":"צור קשר","sections":[{"id":"door","type":"contact-door","schema_version":1,"visible":true,"payload":{"crumb":"צור קשר","kicker":"הדלת פתוחה","title":"בואי נדבר.","body":"אם הגעת עד לפה, כנראה משהו כבר מדבר אלייך. אין צורך להחליט על כלום עכשיו: נתחיל בשיחת היכרות קצרה, בלי התחייבות ובלי לחץ. אספר לך איך אני עובדת, את תספרי לי מה קורה אצלך, ומשם נחליט ביחד.","bodyAccent":"בלי התחייבות","cta":"בואי נדבר","ctaSub":"שיחת היכרות חינם","promise":"אני חוזרת אלייך אישית, עד 4 ימי עסקים.","place":"ברעננה, ואונליין מכל מקום בארץ.","trustToken":"דיאטנית קלינית מוסמכת · R.D. · רישיון משרד הבריאות"}},{"id":"lead","type":"contact-lead","schema_version":1,"visible":true,"payload":{"title":"הצעד הראשון הוא רק שיחה.","titleAccent":"רק שיחה.","body":"כמו שאמרתי למעלה: שיחה אחת קצרה, בלי התחייבות ובלי לחץ. משם נחליט ביחד, בלי למחוק שום דבר שאת אוהבת לאכול.","packages":"הליווי נמכר בחבילות שמתאימות לחיים שלך. איזו חבילה מתאימה לך וכמה היא עולה, אלה דברים שאני אומרת לך בשיחה עצמה, בפשטות.","nameLabel":"שם","phoneLabel":"טלפון / וואטסאפ","messageLabel":"מה הכי מעסיק אותך עכשיו? (לא חובה)","emailLabel":"אימייל","consentLabel":"אני מאשרת שאלונה תחזור אליי בטלפון / וואטסאפ / מייל","submitLabel":"בואי נדבר, שיחת היכרות חינם","submittingLabel":"שולח…","whatsappLabel":"מעדיפה לכתוב? דברי איתי ישירות בוואטסאפ","thanks":"קיבלתי את הפנייה שלך. אני חוזרת אלייך אישית, עד 4 ימי עסקים, בערוץ שבחרת. עד אז, את מוזמנת להציץ במתכונים ולנשום קצת.","thanksLink":"להציץ במתכונים","promise":"אני חוזרת אלייך אישית, עד 4 ימי עסקים.","place":"קליניקה ברעננה · ליווי אונליין בכל הארץ","trustToken":"דיאטנית קלינית מוסמכת · R.D. · רישיון משרד הבריאות"}},{"id":"where","type":"contact-where","schema_version":1,"visible":true,"payload":{"kicker":"איפה נפגשות","title":"איפה שנוח לך:\nאונליין בכל הארץ, או בקליניקה ברעננה","body":"רוב הליווי מתקיים אונליין, מכל מקום בארץ, בלי לצאת מהבית ובלי לאבד זמן על נסיעות. ואם נוח לך פנים-אל-פנים, יש קליניקה ברעננה. נמצא יחד את הדרך שמתאימה לחיים שלך.","items":[{"title":"ליווי אונליין בכל הארץ","body":"מהסלון שלך, מתי שמתאים. הכול מרחוק."},{"title":"קליניקה ברעננה","body":"מעדיפה פנים-אל-פנים? יש גם מקום לשבת בו."},{"title":"וואטסאפ בין הפגישות","body":"לא נעלמת. ערוץ אמיתי לשאלות קטנות בדרך, בחבילות הליווי."}],"chip":"אני חוזרת אלייך אישית, עד 4 ימי עסקים.","socialLabel":"ואפשר גם פשוט לעקוב"}}],"baseline_order":[{"id":"door","type":"contact-door"},{"id":"lead","type":"contact-lead"},{"id":"where","type":"contact-where"}]}'::jsonb)
